'use client';
import dynamic from 'next/dynamic';
import { useEffect, useMemo, useState } from 'react';
import { Activity, AlertTriangle, ArrowDown, ArrowLeft, ArrowRight, BadgeCheck, Cable, Camera, Check, ChevronDown, CircleHelp, Cpu, Eye, EyeOff, Focus, Gauge, Layers3, Maximize2, Menu, MousePointer2, RotateCcw, ShieldAlert, SlidersHorizontal, Sparkles, Volume2, Wifi, X } from 'lucide-react';
import { connections, parts, steps } from '@/lib/data';
const LabScene = dynamic(()=>import('@/components/LabScene'),{ssr:false,loading:()=> <div className="scene-loading"><div className="loader"/><span>Preparando laboratório 3D…</span></div>});
const partImage:Record<string,string>={'esp32':'/Captura de tela de 2026-10-14 11-21-31.png','lora':'/Captura de tela de 2026-10-14 11-21-29.png','sensor':'/Captura de tela de 2026-10-14 11-21-38.png','level':'/Captura de tela de 2026-10-14 11-21-40.png','transducer':'/Captura de tela de 2026-10-14 11-21-38.png'};
const labels:Record<string,{title:string,sub:string,voltage:string}>={esp32:{title:'ESP32-C3 Super Mini',sub:'Controlador central',voltage:'3,3 V'},lora:{title:'SX1278 LoRa',sub:'Transceptor 433 MHz',voltage:'A confirmar'},sensor:{title:'JSN-SR04T',sub:'Placa controladora',voltage:'5 V*'},level:{title:'Conversor lógico',sub:'Bidirecional · 4 canais',voltage:'HV / LV'},transducer:{title:'Transdutor JSN',sub:'Sensor ultrassônico',voltage:'via controlador'}};
export default function Page(){
 const [step,setStep]=useState(0),[selected,setSelected]=useState('esp32'),[done,setDone]=useState<number[]>([]),[showWires,setShowWires]=useState(true),[mode,setMode]=useState<'guided'|'explore'>('guided'),[showPins,setShowPins]=useState(false),[fullscreen,setFullscreen]=useState(false),[unit,setUnit]=useState(1),[mobilePanel,setMobilePanel]=useState(false),[mobileRight,setMobileRight]=useState(false),[toast,setToast]=useState('');
 useEffect(()=>{try{const s=localStorage.getItem('lab-progress');if(s)setDone(JSON.parse(s))}catch{}},[]);
 const progress=Math.round(done.length/steps.length*100), current=steps[step], selectedInfo=labels[selected]||labels.esp32;
 const pin = selected==='esp32'?parts[0].pins?.[0]:undefined;
 const mark=(index:number)=>{const n=done.includes(index)?done.filter(x=>x!==index):[...done,index];setDone(n);localStorage.setItem('lab-progress',JSON.stringify(n));};
 const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),2400)};
 const next=()=>{if(step<steps.length-1)setStep(step+1);else notify('Você chegou ao fim do roteiro.')};
 useEffect(()=>{const fn=(e:KeyboardEvent)=>{if(e.key==='ArrowRight')setStep(s=>Math.min(steps.length-1,s+1));if(e.key==='ArrowLeft')setStep(s=>Math.max(0,s-1));if(e.key.toLowerCase()==='w')setShowWires(v=>!v);if(e.key==='Escape')setFullscreen(false)};window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[]);
 const downloadCSV=()=>{const text='Origem,Destino,Sinal,Tensão,Status\n'+connections.map(c=>`${c.from},${c.to},${c.signal},${c.voltage},${c.status}`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv'}));a.download='tabela-de-conexoes-pendentes.csv';a.click();URL.revokeObjectURL(a.href);notify('Tabela de conexões exportada.')};
 return <main className={fullscreen?'app fullscreen':'app'}>
  <header className="topbar"><a className="brand" href="#"><div className="brand-mark"><Activity size={19}/></div><div><strong>CIRCUIT<span>LAB</span></strong><small>VIRTUAL ENGINEERING ENVIRONMENT</small></div></a><div className="top-center"><div className="live-dot"/> AMBIENTE DE MONTAGEM <span className="top-divider"/> PROJETO 01 <span className="version">BETA 0.9</span></div><div className="top-actions"><button className="unit-switch" onClick={()=>setUnit(unit===1?2:1)}><span className="unit-light"/> UNIDADE 0{unit}<ChevronDown size={14}/></button><button className="icon-button" title="Ajuda" onClick={()=>notify('Modelos provisórios; conexões seguem pendentes de validação.')}><CircleHelp size={18}/></button><div className="avatar">V</div><button className="mobile-menu" title="Detalhes técnicos" onClick={()=>setMobileRight(v=>!v)}><Focus/></button><button className="mobile-menu" title="Instruções" onClick={()=>setMobilePanel(v=>!v)}><Menu/></button></div></header>
  <div className="workspace">
   <aside className={`left-panel ${mobilePanel?'open':''}`}>
    <div className="panel-heading"><div><div className="eyebrow">ROTEIRO DE MONTAGEM</div><h1>Montagem guiada</h1></div><button className="quiet-icon" onClick={()=>setMode(mode==='guided'?'explore':'guided')} title="Alternar modo"><SlidersHorizontal size={17}/></button></div>
    <div className="progress-card"><div className="progress-line"><span>PROGRESSO DO PROJETO</span><b>{progress}%</b></div><div className="progress-track"><i style={{width:`${progress}%`}}/></div><div className="progress-foot"><span>{done.length} de {steps.length} etapas</span><span>Unidade 0{unit}</span></div></div>
    <div className="step-scroll"><div className="section-label">ETAPA ATUAL <span>{String(step+1).padStart(2,'0')} / {String(steps.length).padStart(2,'0')}</span></div><div className="step-card"><div className="step-kicker"><span className="step-dot"/>{current.chapter}</div><h2>{current.title}</h2><p>{current.description}</p><div className="involved"><span>COMPONENTES ENVOLVIDOS</span><div className="involved-items"><button onClick={()=>setSelected('esp32')}><span className="tiny-board green"/>ESP32-C3</button><ArrowRight size={13}/><button onClick={()=>setSelected(step===3?'sensor':'lora')}><span className="tiny-board blue"/>{step===3?'JSN-SR04T':'SX1278'}</button></div></div>
    {current.alert&&<div className="alert-box"><AlertTriangle size={17}/><div><b>ATENÇÃO</b><p>{current.alert}</p></div></div>}
    <div className="tech-note"><div className="note-icon"><ShieldAlert size={15}/></div><p>{current.detail}</p></div>
    <div className="check-row" onClick={()=>mark(step)}><button className={`check-square ${done.includes(step)?'checked':''}`}>{done.includes(step)&&<Check size={13}/>}</button><span>Conferi esta etapa na bancada</span></div>
   </div>
   <div className="step-list"><div className="section-label">CAPÍTULOS</div>{steps.map((s,i)=><button key={i} className={`chapter-row ${i===step?'active':''}`} onClick={()=>setStep(i)}><span className={`chapter-icon ${done.includes(i)?'complete':''}`}>{done.includes(i)?<Check size={13}/>:String(i+1).padStart(2,'0')}</span><span className="chapter-name"><b>{s.title}</b><small>{s.chapter}</small></span>{s.status==='safe'?<BadgeCheck size={15} className="verified-icon"/>:<span className="pending-dot"/>}</button>)}</div>
   </div>
    <div className="left-bottom"><button className="reset-btn" onClick={()=>{setDone([]);localStorage.removeItem('lab-progress');notify('Progresso reiniciado.')}}><RotateCcw size={14}/> Reiniciar progresso</button><div className="keyboard-hint">ATALHOS <kbd>←</kbd><kbd>→</kbd> navegar <kbd>W</kbd> fios</div></div>
   </aside>
   <section className="center-stage">
    <div className="scene-top"><div className="scene-title"><span className="scene-kicker"><span className="live-dot"/> LABORATÓRIO 3D</span><h2>{mode==='guided'?'Bancada de montagem':'Exploração livre'} <span className="scene-breadcrumb">/ Unidade 0{unit}</span></h2></div><div className="scene-actions"><button className={`tool-pill ${mode==='explore'?'selected':''}`} onClick={()=>setMode(mode==='guided'?'explore':'guided')}><MousePointer2 size={15}/>{mode==='guided'?'Modo guiado':'Explorar'}</button><button className="tool-square" title="Capturar imagem" onClick={()=>{const canvas=document.querySelector('canvas');if(canvas){const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='circuit-lab-montagem.png';a.click();notify('Imagem da bancada salva.')}}}><Camera size={16}/></button><button className="tool-square" title="Tela cheia" onClick={()=>setFullscreen(v=>!v)}><Maximize2 size={16}/></button></div></div>
    <div className="scene-wrap"><LabScene selected={selected} onSelect={setSelected} showWires={showWires}/><div className="scene-vignette"/><div className="scene-status"><span className="status-pip"/> RENDERIZAÇÃO EM TEMPO REAL <span className="scene-sep"/> WEBGL</div><div className="scene-coordinates">X <b>00.00</b> &nbsp; Y <b>00.00</b> &nbsp; Z <b>00.00</b></div><div className="annotation"><span className="annotation-line"/><span className="annotation-node"/><div><b>{selectedInfo.title}</b><small>{selectedInfo.sub}</small></div></div><div className="orbit-hint"><RotateCcw size={13}/> ARRASTE PARA ORBITAR <span/> SCROLL PARA ZOOM</div><div className="scene-controls"><button onClick={()=>setShowWires(!showWires)} className={showWires?'on':''}>{showWires?<Cable size={16}/>:<EyeOff size={16}/>}</button><button onClick={()=>setShowPins(!showPins)} className={showPins?'on':''} title="Inspecionar pinos"><Focus size={16}/></button><button onClick={()=>notify('Câmera reposicionada no laboratório.')}><RotateCcw size={16}/></button></div><div className="zoom-controls"><button onClick={()=>notify('Use o scroll para ajustar o zoom.')}><span>＋</span></button><i/><button onClick={()=>notify('Use o scroll para ajustar o zoom.')}><span>−</span></button></div></div>
    <div className="scene-footer"><div className="legend"><span><i className="legend-dot orange"/> Alimentação</span><span><i className="legend-dot blue"/> Dados</span><span><i className="legend-dot purple"/> Sinal</span><span className="legend-pending"><span className="pending-dot"/> Ligações pendentes</span></div><button className="export-btn" onClick={downloadCSV}><Layers3 size={15}/> Exportar tabela <ArrowDown size={13}/></button></div>
    <div className="step-navigation"><button className="nav-back" onClick={()=>setStep(Math.max(0,step-1))} disabled={step===0}><ArrowLeft size={16}/> ANTERIOR</button><div className="nav-progress">{steps.map((_,i)=><button key={i} aria-label={`Ir à etapa ${i+1}`} onClick={()=>setStep(i)} className={i===step?'current':done.includes(i)?'done':''}/>)}</div><button className="nav-next" onClick={next}>PRÓXIMA ETAPA <ArrowRight size={15}/></button></div>
   </section>
   <aside className={`right-panel ${mobileRight?'open':''}`}><div className="right-heading"><div><div className="eyebrow">INSPEÇÃO DO SISTEMA</div><h2>Detalhes técnicos</h2></div><span className="inspect-icon"><Focus size={16}/></span></div><div className="selected-card"><div className="selected-thumb" style={{backgroundImage:`url("${partImage[selected]||partImage.esp32}")`}}/><div className="selected-name"><div className="selected-eyebrow">ELEMENTO SELECIONADO</div><h3>{selectedInfo.title}</h3><span>{selectedInfo.sub}</span></div><button className="quiet-icon"><Eye size={16}/></button></div>
    <div className="detail-tabs"><button className="tab-active">VISÃO GERAL</button><button onClick={()=>setShowPins(true)}>PINAGEM <span className="tab-count">08</span></button></div>
    {showPins?<div className="pin-list"><div className="section-label">PONTOS DE CONEXÃO <span>PROVISÓRIO</span></div>{parts[0].pins?.map((p,i)=><button className="pin-row" key={i} onClick={()=>setSelected('esp32')}><span className="pin-num">{String(i+1).padStart(2,'0')}</span><b>{p.name}</b><small>{p.fn}</small><span className="pending-dot"/></button>)}</div>:<div className="tech-content"><div className="detail-status"><div className="pending-badge"><span className="pending-dot"/> NÃO VALIDADO</div><span>REF. FOTOGRÁFICA</span></div><p className="detail-copy">{selected==='esp32'?'Placa compacta com ESP32-C3 e conector USB-C. A fotografia mostra o lado dos componentes; inscrições e revisão da placa precisam ser conferidas antes de mapear os GPIOs.':'Representação provisória baseada na fotografia do produto. Confirme a revisão, os terminais e o datasheet antes de conectar.'}</p><div className="spec-grid"><div><span>ALIMENTAÇÃO</span><b>{selectedInfo.voltage}</b></div><div><span>INTERFACE</span><b>{selected==='lora'?'SPI':selected==='sensor'?'TRIG / ECHO':'GPIO'}</b></div><div><span>ORIGEM</span><b>{selectedInfo.title}</b></div><div><span>STATUS DE MODELO</span><b className="amber">Provisório</b></div></div><div className="section-label connection-label">CONEXÕES DESTE COMPONENTE <button onClick={()=>setShowWires(!showWires)}>{showWires?'OCULTAR':'EXIBIR'}</button></div><div className="connection-list">{connections.slice(0,2).map((c,i)=><div key={i} className="connection-row"><span className="connection-color" style={{background:c.color}}/><div><b>{c.from.split(' · ')[1]} <ArrowRight size={11}/> {c.to.split(' · ')[1]}</b><small>{c.signal} · {c.voltage}</small></div><span className="pending-dot"/></div>)}</div></div>}
    <div className="right-bottom"><div className="support-note"><ShieldAlert size={16}/><p><b>Segurança elétrica</b><br/>Conexões só serão instruções definitivas após validar as fotografias e documentação do hardware.</p></div><button className="component-library" onClick={()=>notify('Biblioteca: 4 componentes identificados nas referências.')}><span><Layers3 size={16}/></span> Biblioteca de componentes <ArrowRight size={15}/></button></div></aside>
  </div>{toast&&<div className="toast"><Sparkles size={15}/>{toast}</div>}
 </main>
}
